#include <bits/stdc++.h>
using namespace std;

struct Record { string merchant, type; int added, expires; };

int main() {
    vector<string> lines;
    for (string line; getline(cin, line);) {
        size_t a = line.find_first_not_of(" \t\r\n"), b = line.find_last_not_of(" \t\r\n");
        if (a != string::npos) lines.push_back(line.substr(a, b - a + 1));
    }
    size_t cur = 0;
    int days = stoi(lines[cur++]);
    vector<Record> active;
    vector<string> out;
    for (int day = 1; day <= days; day++) {
        int count = stoi(lines[cur++]);
        for (int i = 0; i < count; i++) {
            istringstream in(lines[cur++]);
            string m, t;
            int duration;
            in >> m >> t >> duration;
            active.push_back({m, t, day, day + duration});
        }
        // Merchants grouped by link type among associations active today.
        map<string, set<string>> members;
        for (auto &r : active)
            if (r.added <= day && day < r.expires) members[r.type].insert(r.merchant);
        map<string, set<string>> graph;
        for (auto &[type, group] : members) {
            for (auto &m : group) graph[m];
            for (auto i = group.begin(); i != group.end(); ++i)
                for (auto j = next(i); j != group.end(); ++j) { graph[*i].insert(*j); graph[*j].insert(*i); }
        }
        set<string> visited;
        vector<pair<int, string>> clusters; // (size, pin)
        for (auto &[start, _] : graph) {
            if (visited.count(start)) continue;
            vector<string> stack = {start}, component;
            visited.insert(start);
            while (!stack.empty()) {
                string m = stack.back();
                stack.pop_back();
                component.push_back(m);
                for (auto &nb : graph[m])
                    if (visited.insert(nb).second) stack.push_back(nb);
            }
            // Pin: highest degree, ties to the smallest ID.
            string pin = component[0];
            for (auto &m : component) {
                size_t dm = graph[m].size(), dp = graph[pin].size();
                if (dm > dp || (dm == dp && m < pin)) pin = m;
            }
            clusters.push_back({(int)component.size(), pin});
        }
        sort(clusters.begin(), clusters.end(), [](auto &a, auto &b) {
            return a.first != b.first ? a.first > b.first : a.second < b.second;
        });
        out.push_back("Day " + to_string(day));
        for (auto &[size, pin] : clusters) out.push_back("  cluster size=" + to_string(size) + " pin=" + pin);
    }
    string s;
    for (size_t i = 0; i < out.size(); i++) { if (i) s += '\n'; s += out[i]; }
    s += '\n';
    fwrite(s.data(), 1, s.size(), stdout);
}

import java.io.*;
import java.util.*;

public class Main {
    record Rec(String merchant, String type, int added, int expires) {}

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        List<String> lines = new ArrayList<>();
        for (String line; (line = br.readLine()) != null;) {
            line = line.strip();
            if (!line.isEmpty()) lines.add(line);
        }
        int cur = 0;
        int days = Integer.parseInt(lines.get(cur++));
        List<Rec> active = new ArrayList<>();
        List<String> out = new ArrayList<>();
        for (int day = 1; day <= days; day++) {
            int count = Integer.parseInt(lines.get(cur++));
            for (int i = 0; i < count; i++) {
                String[] p = lines.get(cur++).split("\\s+");
                active.add(new Rec(p[0], p[1], day, day + Integer.parseInt(p[2])));
            }
            // Merchants grouped by link type among associations active today.
            Map<String, TreeSet<String>> members = new HashMap<>();
            for (Rec r : active)
                if (r.added() <= day && day < r.expires()) members.computeIfAbsent(r.type(), k -> new TreeSet<>()).add(r.merchant());
            TreeMap<String, Set<String>> graph = new TreeMap<>();
            for (TreeSet<String> group : members.values()) {
                List<String> ordered = new ArrayList<>(group);
                for (String m : ordered) graph.computeIfAbsent(m, k -> new HashSet<>());
                for (int i = 0; i < ordered.size(); i++)
                    for (int j = i + 1; j < ordered.size(); j++) {
                        graph.get(ordered.get(i)).add(ordered.get(j));
                        graph.get(ordered.get(j)).add(ordered.get(i));
                    }
            }
            Set<String> visited = new HashSet<>();
            List<Object[]> clusters = new ArrayList<>();
            for (String start : graph.keySet()) {
                if (visited.contains(start)) continue;
                Deque<String> stack = new ArrayDeque<>();
                stack.push(start);
                visited.add(start);
                List<String> component = new ArrayList<>();
                while (!stack.isEmpty()) {
                    String m = stack.pop();
                    component.add(m);
                    for (String nb : graph.get(m)) if (visited.add(nb)) stack.push(nb);
                }
                // Pin: highest degree, ties to the smallest ID.
                String pin = component.get(0);
                for (String m : component) {
                    int dm = graph.get(m).size(), dp = graph.get(pin).size();
                    if (dm > dp || (dm == dp && m.compareTo(pin) < 0)) pin = m;
                }
                clusters.add(new Object[]{component.size(), pin});
            }
            clusters.sort((a, b) -> (int) a[0] != (int) b[0] ? Integer.compare((int) b[0], (int) a[0]) : ((String) a[1]).compareTo((String) b[1]));
            out.add("Day " + day);
            for (Object[] c : clusters) out.add("  cluster size=" + c[0] + " pin=" + c[1]);
        }
        System.out.print(String.join("\n", out) + "\n");
    }
}

package main

import (
	"bufio"
	"os"
	"sort"
	"strconv"
	"strings"
)

type record struct {
	merchant, kind  string
	added, expires int
}

type cluster struct {
	size int
	pin  string
}

func main() {
	sc := bufio.NewScanner(os.Stdin)
	var lines []string
	for sc.Scan() {
		if t := strings.TrimSpace(sc.Text()); t != "" {
			lines = append(lines, t)
		}
	}
	cur := 0
	days, _ := strconv.Atoi(lines[cur])
	cur++
	var active []record
	var out []string
	for day := 1; day <= days; day++ {
		count, _ := strconv.Atoi(lines[cur])
		cur++
		for i := 0; i < count; i++ {
			p := strings.Fields(lines[cur])
			cur++
			d, _ := strconv.Atoi(p[2])
			active = append(active, record{p[0], p[1], day, day + d})
		}
		// Merchants grouped by link type among associations active today.
		members := map[string]map[string]bool{}
		for _, r := range active {
			if r.added <= day && day < r.expires {
				if members[r.kind] == nil {
					members[r.kind] = map[string]bool{}
				}
				members[r.kind][r.merchant] = true
			}
		}
		graph := map[string]map[string]bool{}
		for _, group := range members {
			var ordered []string
			for m := range group {
				ordered = append(ordered, m)
				if graph[m] == nil {
					graph[m] = map[string]bool{}
				}
			}
			for i := range ordered {
				for j := i + 1; j < len(ordered); j++ {
					graph[ordered[i]][ordered[j]] = true
					graph[ordered[j]][ordered[i]] = true
				}
			}
		}
		starts := make([]string, 0, len(graph))
		for m := range graph {
			starts = append(starts, m)
		}
		sort.Strings(starts)
		visited := map[string]bool{}
		var clusters []cluster
		for _, start := range starts {
			if visited[start] {
				continue
			}
			stack := []string{start}
			visited[start] = true
			var component []string
			for len(stack) > 0 {
				m := stack[len(stack)-1]
				stack = stack[:len(stack)-1]
				component = append(component, m)
				for nb := range graph[m] {
					if !visited[nb] {
						visited[nb] = true
						stack = append(stack, nb)
					}
				}
			}
			// Pin: highest degree, ties to the smallest ID.
			pin := component[0]
			for _, m := range component {
				dm, dp := len(graph[m]), len(graph[pin])
				if dm > dp || (dm == dp && m < pin) {
					pin = m
				}
			}
			clusters = append(clusters, cluster{len(component), pin})
		}
		sort.Slice(clusters, func(i, j int) bool {
			if clusters[i].size != clusters[j].size {
				return clusters[i].size > clusters[j].size
			}
			return clusters[i].pin < clusters[j].pin
		})
		out = append(out, "Day "+strconv.Itoa(day))
		for _, c := range clusters {
			out = append(out, "  cluster size="+strconv.Itoa(c.size)+" pin="+c.pin)
		}
	}
	w := bufio.NewWriter(os.Stdout)
	defer w.Flush()
	w.WriteString(strings.Join(out, "\n") + "\n")
}
